// slide-01.js — Cover Page
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'SmolVLM: Redefining Small and Efficient Multimodal Models'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Right side decorative blocks representing architecture pipeline
  const blockColors = [theme.secondary, theme.accent, theme.light, theme.accent, theme.secondary];
  const blockX = 6.2;
  const blockW = 0.9;
  const blockH = 0.7;
  const blockGap = 0.12;
  const startY = 0.6;
  for (let i = 0; i < 5; i++) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: blockX, y: startY + i * (blockH + blockGap), w: blockW, h: blockH,
      fill: { color: blockColors[i] }, transparency: 30
    });
  }
  // Second column offset
  for (let i = 0; i < 4; i++) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: blockX + blockW + blockGap, y: startY + 0.4 + i * (blockH + blockGap), w: blockW, h: blockH,
      fill: { color: blockColors[i + 1] }, transparency: 45
    });
  }
  // Third column
  for (let i = 0; i < 3; i++) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: blockX + 2 * (blockW + blockGap), y: startY + 0.8 + i * (blockH + blockGap), w: blockW, h: blockH,
      fill: { color: blockColors[i] }, transparency: 55
    });
  }

  // Horizontal accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 2.3, w: 2.0, h: 0.06,
    fill: { color: theme.light }
  });

  // Title
  slide.addText("SmolVLM", {
    x: 0.6, y: 0.6, w: 5.2, h: 1.0,
    fontSize: 54, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "left"
  });

  slide.addText("Redefining Small and Efficient\nMultimodal Models", {
    x: 0.6, y: 1.5, w: 5.2, h: 0.9,
    fontSize: 22, fontFace: "Calibri", color: theme.light, bold: false, align: "left"
  });

  // Authors
  slide.addText("Hugging Face & Stanford University", {
    x: 0.6, y: 2.6, w: 5.0, h: 0.4,
    fontSize: 16, fontFace: "Calibri", color: theme.accent, bold: false, align: "left"
  });

  // Tagline
  slide.addText("Compact Vision-Language Models for Edge Devices", {
    x: 0.6, y: 3.3, w: 5.0, h: 0.4,
    fontSize: 14, fontFace: "Calibri", color: "FFFFFF", bold: false, align: "left", transparency: 40
  });

  // Bottom stats bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 4.6, w: 10, h: 1.025,
    fill: { color: theme.secondary }, transparency: 60
  });

  const stats = [
    { value: "256M–2.2B", label: "Parameters" },
    { value: "<1 GB", label: "GPU RAM (256M)" },
    { value: "80 tok/s", label: "On-Device" },
    { value: "13", label: "Benchmarks" }
  ];
  const statW = 2.2;
  const statStartX = 0.6;
  for (let i = 0; i < stats.length; i++) {
    const sx = statStartX + i * statW;
    slide.addText(stats[i].value, {
      x: sx, y: 4.7, w: statW, h: 0.4,
      fontSize: 20, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "center"
    });
    slide.addText(stats[i].label, {
      x: sx, y: 5.1, w: statW, h: 0.3,
      fontSize: 11, fontFace: "Calibri", color: theme.light, bold: false, align: "center"
    });
  }

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

