// slide-02.js — Problem & Motivation (Comparison layout)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: 'Large VLMs Are Powerful but Impractical for Edge Deployment'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Large VLMs Are Powerful but Impractical for Edge Deployment", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.6,
    fontSize: 26, fontFace: "Georgia", color: theme.primary, bold: true, align: "left"
  });

  // Left column — The Problem
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 1.1, w: 4.4, h: 3.7,
    fill: { color: "FFFFFF" }, rectRadius: 0.05
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 1.1, w: 4.4, h: 0.06,
    fill: { color: theme.secondary }
  });

  slide.addText("THE PROBLEM", {
    x: 0.6, y: 1.25, w: 4.0, h: 0.35,
    fontSize: 13, fontFace: "Calibri", color: theme.secondary, bold: true, align: "left"
  });

  const problemItems = [
    { text: "State-of-the-art VLMs require 20–80B parameters", options: { bullet: true, breakLine: true, fontSize: 13, fontFace: "Calibri", color: theme.primary, bold: false, paraSpaceAfter: 6 } },
    { text: "GPU memory: 15–40+ GB for inference", options: { bullet: true, breakLine: true, fontSize: 13, fontFace: "Calibri", color: theme.primary, bold: false, paraSpaceAfter: 6 } },
    { text: "Cloud dependency introduces latency and privacy risks", options: { bullet: true, breakLine: true, fontSize: 13, fontFace: "Calibri", color: theme.primary, bold: false, paraSpaceAfter: 6 } },
    { text: "Smartphones and edge devices: 4–8 GB RAM total", options: { bullet: true, fontSize: 13, fontFace: "Calibri", color: theme.primary, bold: false, paraSpaceAfter: 6 } }
  ];
  slide.addText(problemItems, { x: 0.6, y: 1.65, w: 4.0, h: 2.5, valign: "top" });

  // Right column — The Gap (stat callouts)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: 1.1, w: 4.5, h: 3.7,
    fill: { color: "FFFFFF" }, rectRadius: 0.05
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: 1.1, w: 4.5, h: 0.06,
    fill: { color: theme.accent }
  });

  slide.addText("THE GAP", {
    x: 5.3, y: 1.25, w: 4.0, h: 0.35,
    fontSize: 13, fontFace: "Calibri", color: theme.accent, bold: true, align: "left"
  });

  // Stat callouts
  const stats = [
    { value: "27.7 GB", label: "Molmo-A1B-7B GPU RAM", color: theme.secondary },
    { value: "80B", label: "Idefics-80B Parameters", color: theme.secondary },
    { value: "300×", label: "Size Gap vs. SmolVLM-256M", color: theme.accent }
  ];
  for (let i = 0; i < stats.length; i++) {
    const sy = 1.75 + i * 1.1;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y: sy, w: 0.06, h: 0.7,
      fill: { color: stats[i].color }
    });
    slide.addText(stats[i].value, {
      x: 5.6, y: sy, w: 3.5, h: 0.4,
      fontSize: 28, fontFace: "Georgia", color: stats[i].color, bold: true, align: "left"
    });
    slide.addText(stats[i].label, {
      x: 5.6, y: sy + 0.38, w: 3.5, h: 0.3,
      fontSize: 12, fontFace: "Calibri", color: theme.primary, bold: false, align: "left", transparency: 40
    });
  }

  // Bottom callout bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 5.0, w: 9.2, h: 0.35,
    fill: { color: theme.primary }
  });
  slide.addText("Edge devices need VLMs that fit in <1 GB RAM — without sacrificing capability", {
    x: 0.6, y: 5.0, w: 8.8, h: 0.35,
    fontSize: 12, fontFace: "Calibri", color: "FFFFFF", bold: false, align: "center", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

