// slide-03.js — Architecture Overview (Process Flow)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 3,
  title: 'SmolVLM Architecture: Image Splitting, Pixel Shuffle, and SmolLM2 Backbone'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("SmolVLM Architecture", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.5,
    fontSize: 26, fontFace: "Georgia", color: theme.primary, bold: true, align: "left"
  });
  slide.addText("Image Splitting → Pixel Shuffle → SmolLM2 Backbone", {
    x: 0.4, y: 0.7, w: 9.2, h: 0.3,
    fontSize: 13, fontFace: "Calibri", color: theme.secondary, bold: false, align: "left"
  });

  // Process flow — 5 steps with arrows
  const steps = [
    { num: "1", title: "Image\nSplitting", desc: "Images split into\nsub-images", color: theme.secondary },
    { num: "2", title: "SigLIP\nEncoder", desc: "93M SigLIP-B/16\nvision encoding", color: theme.accent },
    { num: "3", title: "Pixel\nShuffle", desc: "r² token\ncompression", color: theme.secondary },
    { num: "4", title: "Linear\nProjection", desc: "Map to LM\ninput space", color: theme.accent },
    { num: "5", title: "SmolLM2", desc: "Language model\nbackbone", color: theme.primary }
  ];

  const stepW = 1.5;
  const stepH = 2.0;
  const arrowW = 0.35;
  const totalW = steps.length * stepW + (steps.length - 1) * arrowW;
  const startX = (10 - totalW) / 2;
  const stepY = 1.3;

  for (let i = 0; i < steps.length; i++) {
    const sx = startX + i * (stepW + arrowW);

    // Step card
    slide.addShape(pres.shapes.RECTANGLE, {
      x: sx, y: stepY, w: stepW, h: stepH,
      fill: { color: "FFFFFF" }, rectRadius: 0.05
    });
    // Top accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: sx, y: stepY, w: stepW, h: 0.06,
      fill: { color: steps[i].color }
    });
    // Step number circle
    slide.addShape(pres.shapes.OVAL, {
      x: sx + stepW / 2 - 0.2, y: stepY + 0.2, w: 0.4, h: 0.4,
      fill: { color: steps[i].color }
    });
    slide.addText(steps[i].num, {
      x: sx + stepW / 2 - 0.2, y: stepY + 0.2, w: 0.4, h: 0.4,
      fontSize: 16, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "center", valign: "middle"
    });
    // Title
    slide.addText(steps[i].title, {
      x: sx + 0.05, y: stepY + 0.7, w: stepW - 0.1, h: 0.6,
      fontSize: 13, fontFace: "Georgia", color: theme.primary, bold: true, align: "center", valign: "middle"
    });
    // Description
    slide.addText(steps[i].desc, {
      x: sx + 0.05, y: stepY + 1.35, w: stepW - 0.1, h: 0.5,
      fontSize: 10, fontFace: "Calibri", color: theme.secondary, bold: false, align: "center", valign: "top"
    });

    // Arrow between steps
    if (i < steps.length - 1) {
      const arrowX = sx + stepW + 0.05;
      slide.addShape(pres.shapes.LINE, {
        x: arrowX, y: stepY + stepH / 2, w: arrowW - 0.1, h: 0,
        line: { color: theme.accent, width: 2 }
      });
      // Arrowhead
      slide.addShape(pres.shapes.LINE, {
        x: arrowX + arrowW - 0.2, y: stepY + stepH / 2 - 0.08, w: 0.12, h: 0.16,
        line: { color: theme.accent, width: 2 }
      });
    }
  }

  // Video note
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 3.6, w: 9.2, h: 0.45,
    fill: { color: theme.light }, transparency: 50, rectRadius: 0.03
  });
  slide.addText("Video: Frames are sampled and processed through the same pipeline", {
    x: 0.6, y: 3.6, w: 8.8, h: 0.45,
    fontSize: 12, fontFace: "Calibri", color: theme.primary, bold: false, align: "center", valign: "middle"
  });

  // Three key findings summary
  const findings = [
    { label: "Balanced Encoder-LM Compute", detail: "Smaller encoder for compact LMs" },
    { label: "Aggressive Token Compression", detail: "r=4 pixel shuffle for small models" },
    { label: "Extended Context Length", detail: "2K → 16K via RoPE scaling" }
  ];
  const findW = 2.9;
  const findStartX = 0.55;
  const findY = 4.3;

  for (let i = 0; i < findings.length; i++) {
    const fx = findStartX + i * (findW + 0.2);
    slide.addShape(pres.shapes.RECTANGLE, {
      x: fx, y: findY, w: 0.06, h: 0.7,
      fill: { color: theme.accent }
    });
    slide.addText(findings[i].label, {
      x: fx + 0.15, y: findY, w: findW - 0.15, h: 0.35,
      fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: true, align: "left", valign: "middle"
    });
    slide.addText(findings[i].detail, {
      x: fx + 0.15, y: findY + 0.3, w: findW - 0.15, h: 0.35,
      fontSize: 10, fontFace: "Calibri", color: theme.secondary, bold: false, align: "left", valign: "top"
    });
  }

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

