const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: 'Aggressive Pixel Shuffle (r=4) Cuts Visual Tokens 16× for Small Models'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Aggressive Pixel Shuffle (r=4) Cuts Visual Tokens 16× for Small Models", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.5,
    fontSize: 22, fontFace: "Georgia", color: theme.primary, bold: true, align: "left"
  });
  slide.addText("Finding 3: Aggressive token compression for compact VLMs", {
    x: 0.4, y: 0.7, w: 9.2, h: 0.3,
    fontSize: 13, fontFace: "Calibri", color: theme.accent, bold: true, align: "left"
  });

  // Left side — Pixel Shuffle mechanism diagram
  // Input grid (4x4)
  slide.addText("Input Feature Map", {
    x: 0.5, y: 1.15, w: 2.5, h: 0.3,
    fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: true, align: "center"
  });

  const gridSize = 4;
  const cellSize = 0.32;
  const gridStartX = 0.7;
  const gridStartY = 1.5;
  const gridColors = [theme.accent, theme.secondary, theme.accent, theme.secondary];

  for (let r = 0; r < gridSize; r++) {
    for (let c = 0; c < gridSize; c++) {
      slide.addShape(pres.shapes.RECTANGLE, {
        x: gridStartX + c * cellSize, y: gridStartY + r * cellSize, w: cellSize - 0.02, h: cellSize - 0.02,
        fill: { color: gridColors[(r + c) % 4] }, transparency: 20
      });
    }
  }

  // Arrow
  slide.addShape(pres.shapes.LINE, {
    x: 2.1, y: 2.1, w: 0.6, h: 0,
    line: { color: theme.primary, width: 2 }
  });
  slide.addText("r=4", {
    x: 2.1, y: 1.8, w: 0.6, h: 0.3,
    fontSize: 14, fontFace: "Georgia", color: theme.accent, bold: true, align: "center", valign: "middle"
  });
  slide.addText("shuffle", {
    x: 2.1, y: 2.3, w: 0.6, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: theme.secondary, bold: false, align: "center", valign: "top"
  });

  // Output grid (1x1 with channel expansion indicator)
  slide.addText("Compressed Tokens", {
    x: 2.85, y: 1.15, w: 2.0, h: 0.3,
    fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: true, align: "center"
  });

  const outCellSize = 1.2;
  const outStartX = 3.1;
  const outStartY = 1.5;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: outStartX, y: outStartY, w: outCellSize, h: outCellSize,
    fill: { color: theme.primary }
  });
  slide.addText("1×1\nspatial", {
    x: outStartX, y: outStartY, w: outCellSize, h: outCellSize,
    fontSize: 10, fontFace: "Calibri", color: "FFFFFF", bold: false, align: "center", valign: "middle"
  });
  slide.addText("16× channels", {
    x: outStartX, y: outStartY + outCellSize + 0.05, w: outCellSize, h: 0.25,
    fontSize: 10, fontFace: "Calibri", color: theme.accent, bold: true, align: "center"
  });

  // Left side bottom — reduction summary
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.3, w: 3.9, h: 0.5,
    fill: { color: theme.accent }, rectRadius: 0.03
  });
  slide.addText("16× token reduction at r=4  (r² = 4² = 16)", {
    x: 0.5, y: 3.3, w: 3.9, h: 0.5,
    fontSize: 13, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Mechanism explanation
  slide.addText([
    { text: "Pixel shuffle (space-to-depth) rearranges spatial features into channels:", options: { breakLine: true, fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: false, paraSpaceAfter: 4 } },
    { text: "Spatial tokens reduced by r² (r=4 → 16× fewer tokens)", options: { bullet: true, breakLine: true, fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: false, paraSpaceAfter: 3 } },
    { text: "Channel depth increases to compensate", options: { bullet: true, breakLine: true, fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: false, paraSpaceAfter: 3 } },
    { text: "Eases attention overhead for small models", options: { bullet: true, fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: false } }
  ], { x: 0.5, y: 3.95, w: 3.9, h: 1.4, valign: "top" });

  // Right side — r=2 vs r=4 comparison
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.8, y: 1.1, w: 4.8, h: 4.25,
    fill: { color: "FFFFFF" }, rectRadius: 0.05
  });

  slide.addText("Shuffle Factor Comparison", {
    x: 5.0, y: 1.2, w: 4.4, h: 0.35,
    fontSize: 14, fontFace: "Georgia", color: theme.primary, bold: true, align: "center"
  });

  // Comparison table
  const tableData = [
    [
      { text: "", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "center" } },
      { text: "r=2", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "center" } },
      { text: "r=4", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "center" } }
    ],
    [
      { text: "Token Reduction", options: { fontSize: 10, fontFace: "Calibri", bold: true, color: theme.primary, align: "left" } },
      { text: "4×", options: { fontSize: 10, fontFace: "Calibri", color: theme.primary, align: "center" } },
      { text: "16×", options: { fontSize: 10, fontFace: "Calibri", color: theme.accent, bold: true, align: "center" } }
    ],
    [
      { text: "Best For", options: { fontSize: 10, fontFace: "Calibri", bold: true, color: theme.primary, align: "left" } },
      { text: "Large LMs", options: { fontSize: 10, fontFace: "Calibri", color: theme.primary, align: "center" } },
      { text: "Small LMs", options: { fontSize: 10, fontFace: "Calibri", color: theme.accent, bold: true, align: "center" } }
    ],
    [
      { text: "Attention Load", options: { fontSize: 10, fontFace: "Calibri", bold: true, color: theme.primary, align: "left" } },
      { text: "Moderate", options: { fontSize: 10, fontFace: "Calibri", color: theme.primary, align: "center" } },
      { text: "Minimal", options: { fontSize: 10, fontFace: "Calibri", color: theme.accent, bold: true, align: "center" } }
    ],
    [
      { text: "Long-Context", options: { fontSize: 10, fontFace: "Calibri", bold: true, color: theme.primary, align: "left" } },
      { text: "Standard", options: { fontSize: 10, fontFace: "Calibri", color: theme.primary, align: "center" } },
      { text: "Improved", options: { fontSize: 10, fontFace: "Calibri", color: theme.accent, bold: true, align: "center" } }
    ]
  ];
  slide.addTable(tableData, {
    x: 5.0, y: 1.65, w: 4.4,
    colW: [1.6, 1.3, 1.5],
    border: { pt: 0.5, color: "E2E8F0" },
    rowH: [0.35, 0.35, 0.35, 0.35, 0.35]
  });

  // Takeaway box at bottom of right panel
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.0, y: 3.5, w: 4.4, h: 0.7,
    fill: { color: theme.light }, transparency: 30, rectRadius: 0.03
  });
  slide.addText("Small VLMs benefit from r=4 (16× reduction) while larger models prefer r=2 (4× reduction)", {
    x: 5.1, y: 3.5, w: 4.2, h: 0.7,
    fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: false, align: "left", valign: "middle"
  });

  // Visual token count comparison
  slide.addText("Visual Token Count", {
    x: 5.0, y: 4.35, w: 4.4, h: 0.25,
    fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: true, align: "center"
  });

  // Bar comparison for token counts
  const tokBarY = 4.65;
  const tokBarW = 2.0;
  // r=2 bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.0, y: tokBarY, w: tokBarW, h: 0.3,
    fill: { color: theme.secondary }
  });
  slide.addText("r=2: 4× tokens", {
    x: 5.0, y: tokBarY, w: tokBarW, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: "FFFFFF", bold: false, align: "center", valign: "middle"
  });
  // r=4 bar (shorter)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.0, y: tokBarY + 0.35, w: tokBarW / 4, h: 0.3,
    fill: { color: theme.accent }
  });
  slide.addText("r=4", {
    x: 5.0, y: tokBarY + 0.35, w: tokBarW / 4, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });
  slide.addText("1/4 of r=2 tokens", {
    x: 5.6, y: tokBarY + 0.35, w: 1.5, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: theme.secondary, bold: false, align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

