// slide-06.js — Context Length Scaling (Data Visualization with stat callouts)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 6,
  title: 'Extending Context from 2K to 16K Tokens Unlocks Higher Image Resolution'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Extending Context from 2K to 16K Tokens Unlocks Higher Image Resolution", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.5,
    fontSize: 22, fontFace: "Georgia", color: theme.primary, bold: true, align: "left"
  });
  slide.addText("Finding 2: Context length scaling via RoPE base adjustment", {
    x: 0.4, y: 0.7, w: 9.2, h: 0.3,
    fontSize: 13, fontFace: "Calibri", color: theme.accent, bold: true, align: "left"
  });

  // Left side — Context length progression visual
  const stages = [
    { label: "2K", desc: "Baseline context", color: theme.light, width: 1.0 },
    { label: "8K", desc: "SmolVLM 256M/500M", color: theme.accent, width: 2.0 },
    { label: "16K", desc: "SmolVLM 2.2B", color: theme.primary, width: 3.2 }
  ];

  slide.addText("Context Length Progression", {
    x: 0.5, y: 1.15, w: 4.5, h: 0.3,
    fontSize: 13, fontFace: "Georgia", color: theme.primary, bold: true, align: "left"
  });

  for (let i = 0; i < stages.length; i++) {
    const barY = 1.6 + i * 0.7;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: barY, w: stages[i].width, h: 0.5,
      fill: { color: stages[i].color }, rectRadius: 0.03
    });
    slide.addText(stages[i].label + " tokens", {
      x: 0.6, y: barY, w: stages[i].width - 0.2, h: 0.5,
      fontSize: 14, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "left", valign: "middle"
    });
    slide.addText(stages[i].desc, {
      x: 0.5 + stages[i].width + 0.15, y: barY, w: 2.5, h: 0.5,
      fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: false, align: "left", valign: "middle"
    });
  }

  // RoPE adjustment card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.8, w: 4.5, h: 1.5,
    fill: { color: "FFFFFF" }, rectRadius: 0.05
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.8, w: 4.5, h: 0.06,
    fill: { color: theme.accent }
  });
  slide.addText("RoPE Base Scaling", {
    x: 0.65, y: 3.95, w: 4.2, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: theme.accent, bold: true, align: "left"
  });
  slide.addText([
    { text: "RoPE base: 10K → 273K", options: { breakLine: true, fontSize: 13, fontFace: "Calibri", color: theme.primary, bold: true, paraSpaceAfter: 4 } },
    { text: "Fine-tuning on mixed long/short-context data", options: { bullet: true, breakLine: true, fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: false, paraSpaceAfter: 3 } },
    { text: "2.2B model: 16K context length", options: { bullet: true, breakLine: true, fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: false, paraSpaceAfter: 3 } },
    { text: "256M / 500M: 8K context length", options: { bullet: true, fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: false } }
  ], { x: 0.65, y: 4.25, w: 4.2, h: 1.0, valign: "top" });

  // Right side — Impact explanation
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.15, w: 4.3, h: 4.15,
    fill: { color: "FFFFFF" }, rectRadius: 0.05
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.15, w: 4.3, h: 0.06,
    fill: { color: theme.secondary }
  });

  slide.addText("Why Context Length Matters", {
    x: 5.5, y: 1.3, w: 3.9, h: 0.35,
    fontSize: 14, fontFace: "Georgia", color: theme.primary, bold: true, align: "left"
  });

  const impactItems = [
    { title: "Higher Resolution Input", desc: "More tokens allow processing larger images at higher resolution without aggressive downsampling" },
    { title: "Multi-Image Reasoning", desc: "Longer contexts support multiple images or video frames in a single forward pass" },
    { title: "Detailed Document Understanding", desc: "Extended context enables processing full document pages with rich text and layout" },
    { title: "Video Comprehension", desc: "More frames can be sampled and processed together, improving temporal understanding" }
  ];

  for (let i = 0; i < impactItems.length; i++) {
    const iy = 1.8 + i * 0.85;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.5, y: iy, w: 0.06, h: 0.6,
      fill: { color: theme.accent }
    });
    slide.addText(impactItems[i].title, {
      x: 5.7, y: iy, w: 3.7, h: 0.25,
      fontSize: 11, fontFace: "Calibri", color: theme.primary, bold: true, align: "left"
    });
    slide.addText(impactItems[i].desc, {
      x: 5.7, y: iy + 0.25, w: 3.7, h: 0.4,
      fontSize: 10, fontFace: "Calibri", color: theme.secondary, bold: false, align: "left", valign: "top"
    });
  }

  // Bottom insight bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.5, y: 5.05, w: 3.9, h: 0.25,
    fill: { color: theme.primary }
  });
  slide.addText("8× context extension with minimal parameter overhead", {
    x: 5.5, y: 5.05, w: 3.9, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: "FFFFFF", bold: false, align: "center", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

