// slide-08.js — On-Device Deployment (Data Visualization — stat callouts)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 8,
  title: 'Real-Time Inference on iPhones: Up to 80 Tokens/Second on Apple Silicon'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Real-Time Inference on iPhones", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.5,
    fontSize: 26, fontFace: "Georgia", color: theme.primary, bold: true, align: "left"
  });
  slide.addText("Up to 80 tokens/second on Apple Silicon via HuggingSnap", {
    x: 0.4, y: 0.7, w: 9.2, h: 0.3,
    fontSize: 13, fontFace: "Calibri", color: theme.accent, bold: true, align: "left"
  });

  // Left column — Key throughput stats
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 1.2, w: 4.5, h: 3.7,
    fill: { color: "FFFFFF" }, rectRadius: 0.05
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 1.2, w: 4.5, h: 0.06,
    fill: { color: theme.accent }
  });

  slide.addText("Throughput Benchmarks", {
    x: 0.6, y: 1.35, w: 4.1, h: 0.35,
    fontSize: 14, fontFace: "Georgia", color: theme.primary, bold: true, align: "left"
  });

  // Throughput chart
  slide.addChart(pres.charts.BAR, [
    {
      name: "Tokens/sec (batch=1)",
      labels: ["M1 Max 64GB", "MacBook Air M3 16GB"],
      values: [80, 55]
    }
  ], {
    x: 0.5, y: 1.8, w: 4.2, h: 2.0,
    barDir: "bar",
    chartColors: [theme.accent],
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
    catAxisLabelColor: theme.primary,
    valAxisLabelColor: theme.primary,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 11,
    showLegend: false,
    showTitle: false,
    catAxisLabelFontSize: 10,
    valAxisLabelFontSize: 9,
    valAxisMinVal: 0,
    valAxisMaxVal: 100
  });

  // Batch scaling note
  slide.addText([
    { text: "Batch=64 throughput:", options: { bold: true, fontSize: 11, fontFace: "Calibri", color: theme.primary } },
    { text: " SmolVLM-256M reaches ~1000 tok/s on high-end devices", options: { fontSize: 11, fontFace: "Calibri", color: theme.secondary, bold: false } }
  ], { x: 0.6, y: 4.0, w: 4.1, h: 0.5, valign: "top" });

  // Scaling note
  slide.addText("Throughput scales roughly linearly with batch size for the smallest model", {
    x: 0.6, y: 4.5, w: 4.1, h: 0.3,
    fontSize: 10, fontFace: "Calibri", color: theme.secondary, bold: false, align: "left"
  });

  // Right column — HuggingSnap + deployment info
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 1.2, w: 4.4, h: 1.6,
    fill: { color: theme.primary }, rectRadius: 0.05
  });
  slide.addText("HuggingSnap iOS App", {
    x: 5.4, y: 1.3, w: 4.0, h: 0.35,
    fontSize: 14, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "left"
  });
  slide.addText([
    { text: "Fully local inference — no cloud dependency", options: { bullet: true, breakLine: true, fontSize: 11, fontFace: "Calibri", color: "FFFFFF", bold: false, paraSpaceAfter: 4 } },
    { text: "Processes photos and videos on-device", options: { bullet: true, breakLine: true, fontSize: 11, fontFace: "Calibri", color: "FFFFFF", bold: false, paraSpaceAfter: 4 } },
    { text: "Privacy-preserving by design", options: { bullet: true, fontSize: 11, fontFace: "Calibri", color: "FFFFFF", bold: false } }
  ], { x: 5.4, y: 1.7, w: 4.0, h: 1.0, valign: "top" });

  // Model size cards
  const modelCards = [
    { name: "SmolVLM-256M", ram: "0.8 GB", target: "Smartphones" },
    { name: "SmolVLM-500M", ram: "1.2 GB", target: "Tablets" },
    { name: "SmolVLM-2.2B", ram: "4.9 GB", target: "Laptops" }
  ];

  const cardW = 1.35;
  const cardGap = 0.15;
  const cardStartX = 5.2;
  const cardY = 3.05;

  for (let i = 0; i < modelCards.length; i++) {
    const cx = cardStartX + i * (cardW + cardGap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: 1.85,
      fill: { color: "FFFFFF" }, rectRadius: 0.05
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: 0.06,
      fill: { color: theme.accent }
    });
    slide.addText(modelCards[i].ram, {
      x: cx, y: cardY + 0.15, w: cardW, h: 0.4,
      fontSize: 20, fontFace: "Georgia", color: theme.accent, bold: true, align: "center"
    });
    slide.addText("GPU RAM", {
      x: cx, y: cardY + 0.5, w: cardW, h: 0.2,
      fontSize: 8, fontFace: "Calibri", color: theme.secondary, bold: false, align: "center"
    });
    slide.addText(modelCards[i].name, {
      x: cx, y: cardY + 0.8, w: cardW, h: 0.25,
      fontSize: 10, fontFace: "Calibri", color: theme.primary, bold: true, align: "center"
    });
    slide.addText(modelCards[i].target, {
      x: cx, y: cardY + 1.05, w: cardW, h: 0.25,
      fontSize: 10, fontFace: "Calibri", color: theme.secondary, bold: false, align: "center"
    });
    // Batch=1 indicator
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx + 0.15, y: cardY + 1.35, w: cardW - 0.3, h: 0.3,
      fill: { color: theme.light }, transparency: 30, rectRadius: 0.03
    });
    slide.addText("batch=1", {
      x: cx + 0.15, y: cardY + 1.35, w: cardW - 0.3, h: 0.3,
      fontSize: 9, fontFace: "Calibri", color: theme.primary, bold: false, align: "center", valign: "middle"
    });
  }

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

