  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title
  slide.addText("Key Takeaways", {
    x: 0.4, y: 0.3, w: 9.2, h: 0.6,
    fontSize: 32, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "left"
  });
  slide.addText("Design Principles for Efficient Multimodal Models", {
