    fontSize: 16, fontFace: "Calibri", color: theme.accent, bold: false, align: "left"
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 1.3, w: 2.0, h: 0.04,
    fill: { color: theme.accent }
  });

  // 5 takeaway cards
  const takeaways = [
    { num: "01", title: "Balance Encoder-LM Compute", desc: "Smaller encoders (93M) outperform larger ones (428M) for compact LMs — allocate compute to the language model" },
    { num: "02", title: "Use Aggressive Token Compression", desc: "r=4 pixel shuffle delivers 16× token reduction for small models, easing attention overhead and improving long-context modeling" },
    { num: "03", title: "Extend Context Length", desc: "Scaling from 2K to 16K tokens via RoPE base adjustment unlocks higher resolution and multi-image reasoning" },
    { num: "04", title: "Sub-1GB Inference Is Achievable", desc: "SmolVLM-256M runs at 0.8 GB GPU RAM, outperforming the 300× larger Idefics-80B" },
    { num: "05", title: "Fully Open-Sourced", desc: "All weights, datasets, training code, and HuggingSnap mobile app are open-sourced for reproducibility" }
  ];

  const cardH = 0.6;
  const cardGap = 0.12;
  const startY = 1.55;

  for (let i = 0; i < takeaways.length; i++) {
    const cy = startY + i * (cardH + cardGap);

    // Number badge
    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: cy + 0.08, w: 0.4, h: 0.4,
      fill: { color: theme.accent }
    });
    slide.addText(takeaways[i].num, {
      x: 0.5, y: cy + 0.08, w: 0.4, h: 0.4,
      fontSize: 12, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "center", valign: "middle"
