    // Title
    slide.addText(takeaways[i].title, {
      x: 1.1, y: cy, w: 4.0, h: 0.3,
      fontSize: 14, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "left", valign: "bottom"
    });

    // Description
    slide.addText(takeaways[i].desc, {
