  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.5, y: 1.55, w: 4.1, h: 3.5,
    fill: { color: theme.secondary }, transparency: 40, rectRadius: 0.1
  });

  slide.addText("Architectural efficiency matters more than raw scale.", {
    x: 5.7, y: 1.8, w: 3.7, h: 1.0,
    fontSize: 22, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "left", valign: "middle"
  });

  slide.addText("SmolVLM demonstrates that strategic design choices — balanced compute, aggressive compression, and extended context — enable competitive multimodal performance at a fraction of the resource cost.", {
    x: 5.7, y: 2.85, w: 3.7, h: 1.2,
    fontSize: 12, fontFace: "Calibri", color: theme.light, bold: false, align: "left", valign: "top"
  });

  // Paper reference
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.7, y: 4.2, w: 3.7, h: 0.65,
    fill: { color: "FFFFFF" }, transparency: 85, rectRadius: 0.03
  });
  slide.addText("arXiv: 2504.05299", {
    x: 5.7, y: 4.2, w: 3.7, h: 0.3,
    fontSize: 11, fontFace: "Calibri", color: theme.accent, bold: true, align: "center", valign: "middle"
  });
  slide.addText("Hugging Face & Stanford University", {
    x: 5.7, y: 4.5, w: 3.7, h: 0.25,
    fontSize: 10, fontFace: "Calibri", color: theme.light, bold: false, align: "center", valign: "top"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("9", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

