// slide-04.js — Compute Allocation (Data Visualization — Bar Chart)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 4,
  title: 'Smaller Vision Encoders Outperform Larger Ones in Compact VLMs'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Smaller Vision Encoders Outperform Larger Ones in Compact VLMs", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.5,
    fontSize: 24, fontFace: "Georgia", color: theme.primary, bold: true, align: "left"
  });
  slide.addText("Finding 1: Balanced encoder-LM parameter allocation", {
    x: 0.4, y: 0.7, w: 9.2, h: 0.3,
    fontSize: 13, fontFace: "Calibri", color: theme.accent, bold: true, align: "left"
  });

  // Bar chart — encoder comparison
  slide.addChart(pres.charts.BAR, [
    {
      name: "93M SigLIP-B/16",
      labels: ["135M LM", "360M LM", "1.7B LM"],
      values: [48.2, 53.5, 58.1]
    },
    {
      name: "428M SigLIP-SO400M",
      labels: ["135M LM", "360M LM", "1.7B LM"],
      values: [45.8, 52.0, 59.8]
    }
  ], {
    x: 0.4, y: 1.15, w: 5.5, h: 3.4,
    barDir: "col",
    barGrouping: "clustered",
    chartColors: [theme.accent, theme.secondary],
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
    catAxisLabelColor: theme.primary,
    valAxisLabelColor: theme.primary,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 10,
    showLegend: true,
    legendPos: "b",
    legendFontSize: 10,
    legendColor: theme.primary,
    valAxisMinVal: 40,
    showTitle: false,
    catAxisLabelFontSize: 10,
    valAxisLabelFontSize: 9
  });

  // Right side — Key takeaway cards
  const cardX = 6.2;
  const cardW = 3.4;

  // Card 1: Key finding
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 1.15, w: cardW, h: 1.4,
    fill: { color: "FFFFFF" }, rectRadius: 0.05
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 1.15, w: cardW, h: 0.06,
    fill: { color: theme.accent }
  });
  slide.addText("Key Finding", {
    x: cardX + 0.15, y: 1.3, w: cardW - 0.3, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: theme.accent, bold: true, align: "left"
  });
  slide.addText("93M SigLIP-B/16 outperforms 428M SigLIP-SO400M when paired with the smallest LMs (135M)", {
    x: cardX + 0.15, y: 1.6, w: cardW - 0.3, h: 0.8,
    fontSize: 12, fontFace: "Calibri", color: theme.primary, bold: false, align: "left", valign: "top"
  });

  // Card 2: Crossover point
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 2.75, w: cardW, h: 1.4,
    fill: { color: "FFFFFF" }, rectRadius: 0.05
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 2.75, w: cardW, h: 0.06,
    fill: { color: theme.secondary }
  });
  slide.addText("Crossover Point", {
    x: cardX + 0.15, y: 2.9, w: cardW - 0.3, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: theme.secondary, bold: true, align: "left"
  });
  slide.addText("Only at 1.7B LM scale does the larger encoder justify its 10% parameter overhead", {
    x: cardX + 0.15, y: 3.2, w: cardW - 0.3, h: 0.8,
    fontSize: 12, fontFace: "Calibri", color: theme.primary, bold: false, align: "left", valign: "top"
  });

  // Card 3: Implication
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 4.35, w: cardW, h: 0.8,
    fill: { color: theme.primary }, rectRadius: 0.05
  });
  slide.addText("Implication: Allocate compute to the LM, not the encoder, for compact VLMs", {
    x: cardX + 0.15, y: 4.4, w: cardW - 0.3, h: 0.7,
    fontSize: 12, fontFace: "Calibri", color: "FFFFFF", bold: false, align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

