];
const barMaxW = 2.5;
const barH = 0.35;
const barStartX = 2.3;

for (let i = 0; i < rows.length; i++) {
  const ry = 1.8 + i * 0.95;

  // LM label
  slide.addText(rows[i].label, {
    x: 0.6, y: ry, w: 1.5, h: 0.3,
    fontSize: 12, fontFace: "Georgia", color: theme.primary, bold: true, align: "right", valign: "middle"
  });

  // SigLIP-B/16 bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: barStartX, y: ry, w: rows[i].small * barMaxW / 2.5, h: barH,
    fill: { color: theme.accent }, rectRadius: 0.03
  });

  // SigLIP-SO400M bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: barStartX, y: ry + 0.38, w: rows[i].large * barMaxW / 2.5, h: barH,
    fill: { color: theme.secondary }, rectRadius: 0.03
  });

  // Winner indicator
  const winColor = rows[i].winner === "small" ? theme.accent : theme.secondary;
  slide.addText(rows[i].note, {
    x: barStartX + barMaxW + 0.1, y: ry + 0.08, w: 1.2, h: 0.5,
    fontSize: 9, fontFace: "Calibri", color: winColor, bold: true, align: "left", valign: "middle"
  });
}

// Trend arrow annotation
slide.addShape(pres.shapes.RECTANGLE, {
  x: 0.7, y: 4.1, w: 4.9, h: 0.35,
  fill: { color: theme.light }, transparency: 40, rectRadius: 0.03
});
slide.addText("As LM scale increases, larger encoder becomes justified", {
  x: 0.8, y: 4.1, w: 4.7, h: 0.35,
  fontSize: 10, fontFace: "Calibri", color: theme.primary, bold: false, align: "center", valign: "middle"
});
